import {escapeHTML as e} from './core.js';
import {shortcutLabels,displayCombo} from './practice.js';
export function languageHTML(result,manual=''){
  const groups=[['phrasal','Phrasal verbs · Cụm động từ'],['collocation','Collocations · Cụm từ thường đi cùng']];
  return `<div class="translation-block"><div class="eyebrow">NGHĨA TIẾNG VIỆT</div><p class="translated-text">${e(manual||result.translation)}</p><span class="small muted">${manual?'Bản dịch của bài học':'Dịch máy local · nghĩa tham khảo'}</span></div><div class="phrase-groups">${groups.map(([type,label])=>{const items=result.phrases.filter(p=>p.type===type);return `<section class="phrase-group"><h4>${label}</h4>${items.length?items.map(p=>`<div class="phrase-item"><div><b>${e(p.phrase)}</b>${p.surface.toLowerCase()!==p.phrase?`<span class="phrase-surface">Trong câu: ${e(p.surface)}</span>`:''}<p>${e(p.meaning)}</p></div><button class="btn secondary tiny" data-save-phrase="${e(p.phrase)}" data-meaning="${e(p.meaning)}" data-kind="${type}">Lưu từ</button></div>`).join(''):'<p class="small muted">Chưa nhận diện được cụm thuộc nhóm này.</p>'}</section>`;}).join('')}</div><p class="small muted" style="margin:12px 0 0">Cụm từ được dò theo từ điển, có xét một số dạng chia động từ và cụm tách. Nghĩa cần đối chiếu với ngữ cảnh.</p>`;
}
export function shortcutHTML(keys){return `<div class="shortcut-list">${[['toggle','Phát / tạm dừng'],['replay','Nghe lại câu'],['check','Kiểm tra'],['next','Câu tiếp theo'],['previous','Câu trước']].map(([key,label])=>`<span>${label}</span><kbd>${key==='check'?'Enter: chấm / tiếp':e(displayCombo(keys[key]))}</kbd>`).join('')}</div><button class="text-btn shortcut-settings" data-action="playback-settings">Cài đặt nghe & phím tắt</button>`;}
export function playbackForm(settings,keys){return `<p class="muted small">Tinh chỉnh đoạn nghe và chọn phím phù hợp với bàn phím của bạn. Các cài đặt được lưu trên máy.</p><div class="playback-form"><div class="field"><label for="pb-repeat">Số lần lặp (0 = vô hạn)</label><input id="pb-repeat" type="number" min="0" max="20" step="1" value="${settings.repeat}"></div><div class="field"><label for="pb-gap">Khoảng nghỉ giữa lượt (giây)</label><input id="pb-gap" type="number" min="0" max="15" step=".1" value="${settings.gap}"></div><div class="field"><label for="pb-lead">Thêm trước đầu câu (giây)</label><input id="pb-lead" type="number" min="0" max="2" step=".05" value="${settings.leadIn}"><small>Hữu ích khi transcript cắt sát âm đầu.</small></div><div class="field"><label for="pb-tail">Thêm sau cuối câu (giây)</label><input id="pb-tail" type="number" min="0" max="2" step=".05" value="${settings.tailOut}"><small>Tránh mất phụ âm hoặc từ cuối câu.</small></div></div><label class="toggle-row"><span>Dừng nghe khi kiểm tra đáp án</span><input id="pb-stop-check" type="checkbox" ${settings.stopOnCheck?'checked':''}></label><label class="toggle-row"><span>Tự phát khi chuyển câu</span><input id="pb-auto-play" type="checkbox" ${settings.autoPlay?'checked':''}></label><h3 style="margin-top:25px">Phím tắt</h3><p class="small muted">Chọn ô rồi bấm tổ hợp mới (có Ctrl, Alt hoặc Meta). Enter lần đầu kiểm tra, lần tiếp theo sang câu; bỏ qua Enter khi đang gõ dấu bằng IME.</p><div class="hotkey-editor">${Object.entries(shortcutLabels).map(([key,label])=>`<label>${label}<input data-hotkey="${key}" data-combo="${e(keys[key])}" readonly value="${e(displayCombo(keys[key]))}" aria-label="Phím ${label}" title="Bấm một tổ hợp mới"></label>`).join('')}</div><div id="playback-error" class="error-text" aria-live="polite"></div><div class="modal-footer"><button class="text-btn" data-action="reset-hotkeys">Khôi phục phím mặc định</button><button class="btn primary" data-action="save-playback">Lưu cài đặt</button></div>`;}
